using JamunaBank.Procurement.API.Constants;using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Models;using JamunaBank.Procurement.API.Repositories.Interfaces;using JamunaBank.Procurement.API.Services.Interfaces;
namespace JamunaBank.Procurement.API.Services.Implementations;
public sealed class ProcurementAuthorityService(IProcurementAuthorityRepository repository,ICurrentUserService currentUser):IProcurementAuthorityService{
 public Task<IReadOnlyList<ProcurementAuthorityPendingDto>>GetPendingAsync(CancellationToken c)=>repository.GetPendingAsync(currentUser.EmployeeId,c);public Task<RequisitionDetailDto?>GetDetailAsync(long id,CancellationToken c)=>repository.GetDetailAsync(Valid(id),currentUser.EmployeeId,c);public Task<ProcurementAuthorityReviewContextDto?>GetContextAsync(long id,CancellationToken c)=>repository.GetContextAsync(Valid(id),currentUser.EmployeeId,c);public Task<StoredProcedureResult?>ApproveAsync(long id,string?m,CancellationToken c){Length(m);return repository.ApproveAsync(Valid(id),currentUser.EmployeeId,m?.Trim(),null,c);}public Task<StoredProcedureResult?>RejectAsync(long id,string?m,CancellationToken c)=>repository.RejectAsync(Valid(id),currentUser.EmployeeId,Required(m),c);public Task<StoredProcedureResult?>ForwardAsync(long id,string?m,CancellationToken c){Length(m);return repository.ForwardAsync(Valid(id),currentUser.EmployeeId,m?.Trim(),c);}
 public async Task<ProcurementAuthorityBulkResult>BulkApproveAsync(ProcurementAuthorityBulkApproveRequest r,CancellationToken c){if(r.RequisitionIds is null||r.RequisitionIds.Count==0)throw new ArgumentException("At least one requisition ID is required.");Length(r.Remarks);var ids=r.RequisitionIds.Distinct().ToArray();if(ids.Any(x=>x<=0))throw new ArgumentException("Requisition IDs must be positive.");var pending=(await repository.GetPendingAsync(currentUser.EmployeeId,c)).ToDictionary(x=>x.Id,x=>x.Number);var batch=Guid.NewGuid();var results=new List<ProcurementAuthorityBulkItemResult>();foreach(var id in ids){StoredProcedureResult?x;try{x=await repository.ApproveAsync(id,currentUser.EmployeeId,r.Remarks?.Trim(),batch,c);}catch(OperationCanceledException){throw;}catch(Exception){x=new(ResultCodes.UnexpectedError,"The requisition could not be processed.",id,null);}x??=new(ResultCodes.UnexpectedError,"No result returned.",id,null);pending.TryGetValue(id,out var no);results.Add(new(id,no,x.ResultCode,x.ResultMessage,x.ReferenceNo));}var ok=results.Count(x=>x.ResultCode==ResultCodes.Success);return new(batch,ids.Length,ok,ids.Length-ok,results);}
 private static long Valid(long id){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));return id;}private static string Required(string?m){if(string.IsNullOrWhiteSpace(m))throw new ArgumentException("Remarks are required for reject.");Length(m);return m.Trim();}private static void Length(string?m){if(m?.Length>2000)throw new ArgumentException("Remarks cannot exceed 2000 characters.");}}
